export type Lang = "pt" | "en" | "es";
// Each language by its own name, the same on every screen.
export const LANGS: { id: Lang; name: string }[] = [
  { id: "pt", name: "Português" },
  { id: "en", name: "English" },
  { id: "es", name: "Español" },
];
const byLang: Record<Lang, typeof pt> = { pt, en, es };
const isLang = (v: string): v is Lang => v in byLang;

// The language to open in: the one picked in Account, else the phone's
// (Portuguese for pt-*, Spanish for es-*, English for any other).
export function pickLanguage(saved: string): Lang {
  if (isLang(saved)) return saved;
  const phone = (navigator.language || "").toLowerCase();
  return phone.startsWith("pt") ? "pt" : phone.startsWith("es") ? "es" : "en";
}

// Set by main.ts before the app shows, and again when Account changes it:
// the texts change in place (a copy of the language's, as state), so the
// screens follow without a reload.
export const t: typeof pt = live(structuredClone(pt));
export function setLanguage(lang: string) {
  const l = isLang(lang) ? lang : "en";
  fill(t, structuredClone(byLang[l]));
  document.documentElement.lang = byLang[l].locale;
  document.title = byLang[l].appName;
  shown.lang = l;
}
// fill copies from's texts into to, keeping to's groups (a screen that kept
// t.cal keeps reading the same object, now in the new language).
type Texts = { [k: string]: unknown };
const isTexts = (v: unknown): v is Texts => !!v && typeof v === "object" && !Array.isArray(v);
function fill(to: Texts, from: Texts) {
  for (const [k, v] of Object.entries(from)) {
    const into = to[k];
    if (isTexts(v) && isTexts(into)) fill(into, v);
    else to[k] = v;
  }
}

// fmt puts the values in a text's {names}; plural picks the text for one or
// for many, with the count as {n}.
export function fmt(text: string, values: Record<string, string | number> = {}) {
  return text.replace(/\{(\w+)\}/g, (all, k: string) => (k in values ? String(values[k]) : all));
}
export const plural = (n: number, one: string, many: string, values: Record<string, string | number> = {}) => fmt(n === 1 ? one : many, { ...values, n });
